// Mechanical serialization of the licensed upstream markup for Worker imports.
import { readFile, writeFile } from "node:fs/promises";

const html = await readFile(new URL("../viewer-assets/web/viewer.html", import.meta.url), "utf8");
await writeFile(new URL("../src/pdf-viewer-template.mjs", import.meta.url),
  "// Generated by scripts/prepare-pdfjs-template.mjs; upstream license retained in markup.\n" +
  "export default " + JSON.stringify(html) + ";\n");
